"\n"
"fn __i2f64(v: i64) -> u64 {\n"
"  if v == 0 {\n"
"    return 0;\n"
"  }\n"
"  let s: u64 = if v < 0 { 1 } else { 0 };\n"
"  let mut mag: u64 = v as u64;\n"
"  if s == 1 {\n"
"    mag = 0 - mag;\n"
"  }\n"
"  let n: i64 = __f64_hb(mag);\n"
"  let mut e: i64 = 1023 + n;\n"
"  let mut man: u64 = 0;\n"
"  if n >= 53 {\n"
"    let drop: i64 = n - 52;\n"
"    man = mag >> drop;\n"
"    let g: bool = ((mag >> (drop - 1)) & 1 as u64) != 0;\n"
"    let r: bool = drop >= 2 && ((mag >> (drop - 2)) & 1 as u64) != 0;\n"
"    let st: bool = drop >= 2 && (mag & (((1 << (drop - 2)) - 1) as u64)) != 0;\n"
"    if g && (r || st || (man & 1 as u64) != 0) {\n"
"      man += 1;\n"
"      if (man >> 53) != 0 {\n"
"        man = man >> 1;\n"
"        e += 1;\n"
"      }\n"
"    }\n"
"  } else {\n"
"    man = mag << (52 - n);\n"
"  }\n"
"  return (s << 63) | ((e as u64 & 0x7FF) << 52) | (man & (0x000FFFFFFFFFFFFF as u64));\n"
"}\n"
"\n"
"fn __f32_f64(x: u64) -> u64 {\n"
"  let s: u64 = (x >> 31) & 1;\n"
"  let e8: i64 = ((x >> 23) & 0xFF) as i64;\n"
"  let m: u64 = x & (0x7FFFFF as u64);\n"
"  if e8 == 255 {\n"
"    if m != 0 {\n"
"      return __fnan();\n"
"    }\n"
"    return (s << 63) | 0x7FF0000000000000;\n"
"  }\n"
"  if e8 == 0 {\n"
"    if m == 0 {\n"
"      return s << 63;\n"
"    }\n"
"    let mut mm: u64 = m;\n"
"    let mut k: i64 = 0;\n"
"    loop {\n"
"      if (mm >> 23) != 0 {\n"
"        break;\n"
"      }\n"
"      mm = mm << 1;\n"
"      k += 1;\n"
"    }\n"
"    let e11: i64 = 897 - k;\n"
"    return (s << 63) | ((e11 as u64 & 0x7FF) << 52) | ((mm & (0x7FFFFF as u64)) << 29);\n"
"  }\n"
"  return (s << 63) | (((e8 + 896) as u64 & 0x7FF) << 52) | (m << 29);\n"
"}\n"
"\n"
"fn __f64_f32(x: u64) -> u64 {\n"
"  let s: u64 = x >> 63;\n"
"  let e: i64 = __f64_exp(x);\n"
"  let m: u64 = __f64_mant(x);\n"
"  if e == 0x7FF {\n"
"    if (x & (0x000FFFFFFFFFFFFF as u64)) != 0 {\n"
"      return (s << 31) | 0x7F800000 | 0x400000;\n"
"    }\n"
"    return (s << 31) | 0x7F800000;\n"
"  }\n"
"  if e == 0 && m == 0 {\n"
"    return s << 31;\n"
"  }\n"
"  let mut e32: i64 = e - 1023 + 127;\n"
"  if e == 0 {\n"
"    // f64 subnormal: magnitude below every f32 subnormal unless huge m\n"
"    if __f64_hb(m) + (-1074) < -149 + 22 {\n"
"      return s << 31;\n"
"    }\n"
"    e32 = 1;\n"
"  }\n"
"  if e32 >= 255 {\n"
"    return (s << 31) | 0x7F800000;\n"
"  }\n"
"  let mut man: u64 = m >> 29;\n"
"  let g: bool = ((m >> 28) & 1 as u64) != 0;\n"
"  let r: bool = ((m >> 27) & 1 as u64) != 0;\n"
"  let st: bool = (m & (0x7FFFFFF as u64)) != 0;\n"
"  if g && (r || st || (man & 1 as u64) != 0) {\n"
"    man += 1;\n"
"    if man >> 23 != 0 {\n"
"      man = 0;\n"
"      e32 += 1;\n"
"      if e32 >= 255 {\n"
"        return (s << 31) | 0x7F800000;\n"
"      }\n"
"    }\n"
"  }\n"
"  return (s << 31) | ((e32 as u64 & 0xFF) << 23) | (man & 0x7FFFFF);\n"
"}\n"
"\n"
"// f32 arithmetic wrappers: f32 values are exact in f64, so +- and * get one\n"
"// final rounding on the pack; / double-rounds in rare cases (documented)\n"
"fn __fadd32(a: u64, b: u64) -> u64 {\n"
"  return __f64_f32(__fadd64(__f32_f64(a), __f32_f64(b)));\n"
"}\n"
"\n"
"fn __fsub32(a: u64, b: u64) -> u64 {\n"
"  return __f64_f32(__fsub64(__f32_f64(a), __f32_f64(b)));\n"
"}\n"
"\n"
"fn __fmul32(a: u64, b: u64) -> u64 {\n"
"  return __f64_f32(__fmul64(__f32_f64(a), __f32_f64(b)));\n"
"}\n"
"\n"
"fn __fdiv32(a: u64, b: u64) -> u64 {\n"
"  return __f64_f32(__fdiv64(__f32_f64(a), __f32_f64(b)));\n"
"}\n"
"\n"
"fn __feq32(a: u64, b: u64) -> u64 {\n"
"  return __feq64(__f32_f64(a), __f32_f64(b));\n"
"}\n"
"\n"
"fn __flt32(a: u64, b: u64) -> u64 {\n"
"  return __flt64(__f32_f64(a), __f32_f64(b));\n"
"}\n";
